const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = '-';
const MAX_CODE_POINT = 0x10ffff;

function adapt(delta, numPoints, firstTime) {
  let adjustedDelta = firstTime ? Math.floor(delta / DAMP) : Math.floor(delta / 2);
  adjustedDelta += Math.floor(adjustedDelta / numPoints);

  let k = 0;
  while (adjustedDelta > Math.floor(((BASE - T_MIN) * T_MAX) / 2)) {
    adjustedDelta = Math.floor(adjustedDelta / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor(((BASE - T_MIN + 1) * adjustedDelta) / (adjustedDelta + SKEW));
}

function encodeDigit(digit) {
  if (digit < 26) {
    return String.fromCharCode(97 + digit);
  }

  return String.fromCharCode(22 + digit);
}

function decodeDigit(character) {
  const code = character.codePointAt(0);

  if (code >= 48 && code <= 57) {
    return code - 22;
  }
  if (code >= 65 && code <= 90) {
    return code - 65;
  }
  if (code >= 97 && code <= 122) {
    return code - 97;
  }

  return BASE;
}

export function encodePunycode(input) {
  const codePoints = Array.from(input, (character) => character.codePointAt(0));
  const output = [];

  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;

  for (const codePoint of codePoints) {
    if (codePoint < 0x80) {
      output.push(String.fromCodePoint(codePoint));
    }
  }

  const basicLength = output.length;
  let handledCount = basicLength;

  if (basicLength > 0) {
    output.push(DELIMITER);
  }

  while (handledCount < codePoints.length) {
    let nextCodePoint = Number.POSITIVE_INFINITY;

    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < nextCodePoint) {
        nextCodePoint = codePoint;
      }
    }

    delta += (nextCodePoint - n) * (handledCount + 1);
    n = nextCodePoint;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint !== n) {
        continue;
      }

      let q = delta;
      for (let k = BASE; ; k += BASE) {
        const t =
          k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

        if (q < t) {
          break;
        }

        output.push(encodeDigit(t + ((q - t) % (BASE - t))));
        q = Math.floor((q - t) / (BASE - t));
      }

      output.push(encodeDigit(q));
      bias = adapt(delta, handledCount + 1, handledCount === basicLength);
      delta = 0;
      handledCount += 1;
    }

    delta += 1;
    n += 1;
  }

  return output.join('');
}

export function decodePunycode(input) {
  const output = [];

  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  let index = 0;

  const delimiterIndex = input.lastIndexOf(DELIMITER);
  if (delimiterIndex !== -1) {
    for (let basicIndex = 0; basicIndex < delimiterIndex; basicIndex += 1) {
      const codePoint = input.codePointAt(basicIndex);

      if (codePoint === undefined || codePoint >= 0x80) {
        throw new Error('Invalid A-label');
      }

      output.push(codePoint);
    }

    index = delimiterIndex + 1;
  }

  while (index < input.length) {
    const oldI = i;
    let w = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) {
        throw new Error('Invalid A-label');
      }

      const digit = decodeDigit(input[index]);
      index += 1;

      if (digit >= BASE) {
        throw new Error('Invalid A-label');
      }

      i += digit * w;

      const t =
        k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

      if (digit < t) {
        break;
      }

      w *= BASE - t;
    }

    bias = adapt(i - oldI, output.length + 1, oldI === 0);
    n += Math.floor(i / (output.length + 1));
    i %= output.length + 1;

    if (n > MAX_CODE_POINT) {
      throw new Error('Invalid A-label');
    }

    output.splice(i, 0, n);
    i += 1;
  }

  return String.fromCodePoint(...output);
}

