const MARK_RE = /^\p{M}$/u;
const LETTER_RE = /^\p{L}$/u;
const UPPER_OR_TITLE_RE = /^[\p{Lu}\p{Lt}]$/u;
const VALID_NON_ASCII_RE = /^[\p{Ll}\p{Lm}\p{Lo}\p{Mn}\p{Mc}\p{Nd}\p{Nl}]$/u;
const GREEK_RE = /^\p{Script=Greek}$/u;
const HEBREW_RE = /^\p{Script=Hebrew}$/u;
const ARABIC_RE = /^\p{Script=Arabic}$/u;
const SYRIAC_RE = /^\p{Script=Syriac}$/u;
const THAANA_RE = /^\p{Script=Thaana}$/u;
const NKO_RE = /^\p{Script=Nko}$/u;
const SAMARITAN_RE = /^\p{Script=Samaritan}$/u;
const MANDAIC_RE = /^\p{Script=Mandaic}$/u;
const ADLAM_RE = /^\p{Script=Adlam}$/u;
const HIRAGANA_RE = /^\p{Script=Hiragana}$/u;
const KATAKANA_RE = /^\p{Script=Katakana}$/u;
const HAN_RE = /^\p{Script=Han}$/u;

export function splitCodePoints(value) {
  return Array.from(value);
}

export function codePointLength(value) {
  return splitCodePoints(value).length;
}

export function isAscii(value) {
  return /^[\x00-\x7f]*$/.test(value);
}

export function isAsciiLowercaseLetter(character) {
  return character >= 'a' && character <= 'z';
}

export function isAsciiUppercaseLetter(character) {
  return character >= 'A' && character <= 'Z';
}

export function isAsciiDigit(character) {
  return character >= '0' && character <= '9';
}

export function isCombiningMark(character) {
  return MARK_RE.test(character);
}

export function isLetter(character) {
  return LETTER_RE.test(character);
}

export function isUpperOrTitle(character) {
  return UPPER_OR_TITLE_RE.test(character);
}

export function isValidRegularNonAscii(character) {
  return VALID_NON_ASCII_RE.test(character);
}

export function isGreek(character) {
  return GREEK_RE.test(character);
}

export function isHebrew(character) {
  return HEBREW_RE.test(character);
}

export function isJapaneseScript(character) {
  return HIRAGANA_RE.test(character) || KATAKANA_RE.test(character) || HAN_RE.test(character);
}

export function isArabicIndicDigit(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x0660 && codePoint <= 0x0669;
}

export function isExtendedArabicIndicDigit(character) {
  const codePoint = character.codePointAt(0);
  return codePoint >= 0x06f0 && codePoint <= 0x06f9;
}

export function isRtlLetter(character) {
  if (!isLetter(character)) {
    return false;
  }

  return (
    HEBREW_RE.test(character) ||
    ARABIC_RE.test(character) ||
    SYRIAC_RE.test(character) ||
    THAANA_RE.test(character) ||
    NKO_RE.test(character) ||
    SAMARITAN_RE.test(character) ||
    MANDAIC_RE.test(character) ||
    ADLAM_RE.test(character)
  );
}

export function isContextualCodePoint(character) {
  const codePoint = character.codePointAt(0);

  return (
    codePoint === 0x00b7 ||
    codePoint === 0x0375 ||
    codePoint === 0x05f3 ||
    codePoint === 0x05f4 ||
    codePoint === 0x30fb ||
    codePoint === 0x200c ||
    codePoint === 0x200d
  );
}

export function isContextualCodePointValid(codePoints, index) {
  const character = codePoints[index];
  const codePoint = character.codePointAt(0);

  if (codePoint === 0x00b7) {
    return (
      index > 0 &&
      index < codePoints.length - 1 &&
      codePoints[index - 1] === 'l' &&
      codePoints[index + 1] === 'l'
    );
  }

  if (codePoint === 0x0375) {
    return index < codePoints.length - 1 && isGreek(codePoints[index + 1]);
  }

  if (codePoint === 0x05f3 || codePoint === 0x05f4) {
    return index > 0 && isHebrew(codePoints[index - 1]);
  }

  if (codePoint === 0x30fb) {
    return codePoints.some((candidate) => isJapaneseScript(candidate));
  }

  return false;
}

export function formatCodePoint(codePoint) {
  const rawHex = codePoint.toString(16).toUpperCase();
  return `U+${rawHex.padStart(Math.max(4, rawHex.length), '0')}`;
}

