export class IDNAError extends Error {}

function reprString(value) {
  let output = "'";

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      output += '\\\\';
      continue;
    }
    if (character === "'") {
      output += "\\'";
      continue;
    }
    if (character === '\n') {
      output += '\\n';
      continue;
    }
    if (character === '\r') {
      output += '\\r';
      continue;
    }
    if (character === '\t') {
      output += '\\t';
      continue;
    }
    if (
      codePoint < 0x20 ||
      (codePoint >= 0x7f && codePoint <= 0x9f) ||
      (codePoint >= 0xd800 && codePoint <= 0xdfff)
