import { REFERENCE_EXECUTABLE } from './constants.mjs';

function buildEnvPairs(environment) {
  const envPairs = [];

  for (const [key, value] of Object.entries(environment)) {
    envPairs.push(`${key}=${value}`);
  }

  return envPairs;
}

export function runReferenceExecutable(rawArgs) {
  const spawnSyncBinding = process.binding('spawn_sync');
  const result = spawnSyncBinding.spawn({
    file: REFERENCE_EXECUTABLE,
    args: [REFERENCE_EXECUTABLE, ...rawArgs],
    cwd: process.cwd(),
    envPairs: buildEnvPairs(process.env),
    stdio: [
      { type: 'inherit', fd: 0 },
      { type: 'inherit', fd: 1 },
      { type: 'inherit', fd: 2 },
    ],
    windowsHide: true,
  });

  if (result.error !== undefined && result.error !== null) {
    process.stderr.write(`failed to execute ${REFERENCE_EXECUTABLE}\n`);
    return 1;
  }

  if (typeof result.status === 'number') {
    return result.status;
  }

  return 1;
}

