export function writeLine(text = '') {
  process.stdout.write(`${text}\n`);
}

export function writeErrorLine(text = '') {
  process.stderr.write(`${text}\n`);
}

export function formatPythonBoolean(value) {
  return value ? 'True' : 'False';
}

export function formatPythonBytes(asciiValue) {
  const escaped = asciiValue.replace(/\\/g, '\\\\').replace(/'/g, "\\'");

  return `b'${escaped}'`;
}

